import React, { useState } from 'react';
import { CAsyncSwitch } from '@cloud-materials/common';

export default () => {
  const [value, setValue] = useState(true);
  return (
    <CAsyncSwitch
      value={value}
      closeConfirmTips={'确定关闭吗？'}
      openConfirmTips={'确定开启吗？'}
      onChange={checked =>
        new Promise<any>(rs => {
          setTimeout(() => {
            rs('');
            setValue(checked);
          }, 1000);
        })
      }
    />
  );
};
